import{_ as r,l as o,o as e,c as n,v as t,p as l,x as s,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"全相联对照","description":"","frontmatter":{"title":"全相联对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fully-associative.md","filePath":"cs/fully-associative.md","lastUpdated":1789023840000}'),A={name:"cs/fully-associative.md"};function h(E,a,B,m,_,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="全相联对照" tabindex="-1">全相联对照 <a class="header-anchor" href="#全相联对照" aria-label="Permalink to &quot;全相联对照&quot;">​</a></h1><div class="epigraph"><p>块可以放进任意一行时，冲突缺失消失，比较器却要与行数一起涨；它是组相联在 $n$ 取到总块数时的端点，不是默认的大 cache。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/set-associative-replace">上一课</a>用索引选组、组内多路比标签，并写明 \\(n\\) 等于总块数就是全相联。本课不重讲 LRU 位。缺口是把这个端点单独钉死：没有索引字段，整块地址当标签，用相联存储器（CAM）一次比完；以及它适合小结构（TLB）而不适合兆字节数据 cache。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组相联仍可能在一组内互踢，哪怕别的组空着——那是冲突缺失。把相联度加到「只有一组」，冲突项相对同容量全相联的差额为零。缺口不是新的替换哲学，而是<strong>地址不再切出索引：查找是全体标签并行比较</strong>，命中时间与面积随行数线性变差。</p><p>上一课说常用 2 路或 4 路。本课解释为什么不大到全相联去做数据 cache，却又在 TLB、小 victim 缓冲里用它。</p><p><span class="marginnote">CAM 每行一份比较器。数据 SRAM 可以很大；标签 CAM 做大，时钟和功耗先垮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>全相联 cache：地址切成标签与块内偏移，无索引。\\(N\\) 行则 \\(N\\) 路并行比标签，命中 mux 选出数据。替换在「整个 cache」这一组上做 LRU 或随机；真 LRU 状态随 \\(N\\) 的阶乘涨，实践用近似。</p>',9)),(e(),l(p,null,{default:s(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E5%9C%B0%E5%9D%80%EF%BC%9A%E6%A0%87%E7%AD%BE%2B%E5%81%8F%E7%A7%BB%22%5D%20--%3E%20CAM%5B%22%E5%85%A8%E4%BD%93%E6%A0%87%E7%AD%BE%E5%B9%B6%E8%A1%8C%E6%AF%94%22%5D%0A%20%20CAM%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E4%BB%BB%E4%B8%80%E8%A1%8C%22%5D%0A%20%20CAM%20--%3E%20REPL%5B%22%E7%BC%BA%E5%A4%B1%EF%BC%9A%E5%9C%A8%E5%85%A8%E9%83%A8%E8%A1%8C%E9%87%8C%E6%9B%BF%E6%8D%A2%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>直接映射是 1 路；全相联是 \\(N\\) 路单组。组相联夹在中间。三种映射共享同一套「标签匹配才命中」的语义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>冲突缺失降到零之后，剩下强制与容量。<a href="/cs/cache-miss-types">缺失分类</a>会用「同容量全相联」当参照——本课先把这个参照机器造出来。命中时间上升会吃掉 CPI 收益：阿姆达尔项从缺失停顿转到周期变长。</p><p>TLB 条目少（几十到几百），全相联划算，而且 VPN 不宜随便切索引（页号分布不保证均匀）。数据 L1 要支撑每拍 load，常用低相联度换短命中。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入写回，不讨论 inclusive 层次。victim cache 是「很小的全相联」挂在直接映射旁边，用来收冲突牺牲品，附录手段，主干不依赖。也不把全相联写成「没有替换」：满了仍要踢，只是候选是全体行。</p><p>后课默认：谈到大容量数据 cache，默认组相联；谈到 TLB 或极小缓冲，允许全相联。写策略是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全相联 = 单组、\\(N\\) 路，无索引，冲突缺失为零。</li><li>比较器与真 LRU 随 \\(N\\) 变贵；大数据 cache 不用它当默认。</li><li>写回与脏位是下一课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const T=r(A,[["render",h]]);export{f as __pageData,T as default};
